-- Representative existing schema; no production records or credentials.
CREATE TABLE user_profiles(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "auth_user_id" uuid,
  "email" text,
  "name" text,
  "address" text,
  "oib" text,
  "dob" date,
  "pob" text,
  "mobile" text,
  "is_first_login" boolean,
  "requires_password_change" boolean,
  "requires_authenticator_setup" boolean,
  "authenticator_secret" text,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "role" text,
  "class_id" text,
  "school_id" text,
  "school_year_id" uuid,
  "password_type" text,
  "father_name" text,
  "mother_name" text,
  "birthplace" text,
  "birth_country" text,
  "citizenship" text,
  "student_registry_number" text,
  "gender" text,
  "program_adjustment" text,
  "active_school_id" text,
  "access_role" text,
  "pin_hash" text
);
CREATE TABLE schools(
  "id" text PRIMARY KEY,
  "name" text,
  "type" text,
  "address" text,
  "city" text,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "subtype" text,
  "code" text,
  "oib" text,
  "postal_code" text,
  "country" text,
  "phone" text,
  "email" text,
  "website" text,
  "is_active" boolean,
  "created_by" uuid,
  "education_level" text
);
CREATE TABLE classes(
  "id" text PRIMARY KEY,
  "school_id" text,
  "school_year" text,
  "name" text,
  "grade_level" integer,
  "section" text,
  "status" text,
  "homeroom_teacher_id" uuid,
  "deputy_teacher_id" uuid,
  "program_id" uuid,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "school_year_id" uuid,
  "variant" text,
  "document_klasa" text,
  "document_urbroj" text,
  "document_issue_date" date,
  "deputy_homeroom_teacher_id" uuid,
  "previous_class_id" text,
  "next_class_id" text,
  "is_graduating_class" boolean,
  "is_active" boolean,
  "created_by" uuid
);
CREATE TABLE user_school_roles(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "user_id" uuid,
  "school_id" text,
  "role" text,
  "status" text,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone
);
CREATE TABLE student_class_enrollments(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "student_id" uuid,
  "class_id" text,
  "school_year" text,
  "status" text,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "school_year_id" uuid,
  "program_id" uuid,
  "registry_student_id" uuid,
  "source_school_enrollment_id" uuid,
  "ematica_status" text,
  "ednevnik_data_entry_blocked" boolean,
  "school_enrollment_id" uuid,
  "enrolled_on" date,
  "exited_on" date,
  "exit_reason" text
);
CREATE TABLE class_subject_teachers(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "class_id" text,
  "subject_id" text,
  "teacher_id" uuid,
  "school_id" text,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "group_name" text
);
CREATE TABLE lessons(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "class_id" text,
  "subject_id" text,
  "teacher_id" uuid,
  "date" date,
  "hour" integer,
  "topic" text,
  "homework" text,
  "notes" text,
  "materials" text,
  "group_name" text,
  "is_held" boolean,
  "is_block" boolean,
  "block_count" integer,
  "created_by_user_id" uuid,
  "teacher_display_name" text,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "school_id" text,
  "school_year_id" uuid,
  "work_week_id" uuid
);
CREATE TABLE absences(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "student_id" uuid,
  "lesson_id" uuid,
  "class_id" text,
  "date" date,
  "hour" integer,
  "status" text,
  "note" text,
  "teacher_id" uuid,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "absence_type" text,
  "justified_by" text,
  "resolved_by" uuid,
  "resolved_at" timestamp with time zone
);
CREATE TABLE school_events(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "school_id" text,
  "school_year" text,
  "event_type" text,
  "title" text,
  "description" text,
  "start_date" date,
  "end_date" date,
  "start_time" time without time zone,
  "end_time" time without time zone,
  "is_instructional_day" boolean,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "classroom" text
);
CREATE TABLE work_weeks(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "class_id" text,
  "school_year" text,
  "name" text,
  "start_date" date,
  "end_date" date,
  "shift" text,
  "is_teaching_week" boolean,
  "on_duty_student_ids" uuid[],
  "teaching_days" date[],
  "created_by" uuid,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "school_id" text,
  "school_year_id" uuid,
  "non_teaching_reason" text,
  "week_type" text,
  "holiday_type" text,
  "is_instructional" boolean,
  "non_teaching_reason_note" text
);
CREATE TABLE grades(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "student_id" uuid,
  "subject_id" text,
  "teacher_id" uuid,
  "class_id" text,
  "value" integer,
  "note" text,
  "category" text,
  "weight" integer,
  "is_important" boolean,
  "date" date,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "school_id" text,
  "element" text,
  "grade_type" text,
  "is_final" boolean,
  "period" text
);
CREATE TABLE student_notes(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "student_id" uuid,
  "subject_id" text,
  "teacher_id" uuid,
  "class_id" text,
  "school_id" text,
  "content" text,
  "date" date,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone
);
CREATE TABLE programs(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "name" text,
  "school_id" text,
  "created_at" timestamp with time zone,
  "duration_years" integer,
  "type" text,
  "continuation_type" text,
  "code" text,
  "is_paid_continuation" boolean,
  "is_active" boolean,
  "updated_at" timestamp with time zone,
  "created_by" uuid,
  "admission_track" text,
  "admission_capacity" integer,
  "admission_min_points" numeric,
  "admission_is_open" boolean,
  "module_or_track" text,
  "admission_required_exams" jsonb,
  "admission_elective_exams" jsonb,
  "admission_special_achievements" jsonb,
  "admission_health_considerations" jsonb
);
CREATE TABLE school_document_settings(
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "school_id" text,
  "school_name" text,
  "school_name_print" text,
  "oib" text,
  "city" text,
  "county" text,
  "principal_name" text,
  "principal_title" text,
  "school_number" text,
  "default_klasa" text,
  "default_urbroj" text,
  "stamp_image_url" text,
  "principal_signature_url" text,
  "created_at" timestamp with time zone,
  "updated_at" timestamp with time zone,
  "stamp_url" text,
  "signature_url" text,
  "stamp_path" text,
  "signature_path" text,
  "principal_signature_path" text,
  "teacher_signature_url" text,
  "teacher_signature_path" text,
  "overall_success_label" text,
  "conduct_label" text,
  "certificate_place" text,
  "certificate_date" date,
  "desired_school_name" text,
  "homeroom_teacher_title" text,
  "certificate_template_config" jsonb
);

CREATE TABLE final_grades("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"student_id" uuid,"subject_id" text,"teacher_id" uuid,"class_id" text,"school_id" text,"value" text,"period" text,"date" date,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"term" text,"note" text,"school_year_id" uuid);
